/**
 * Generates the branded HTML email signature for Life180 Labs.
 * Used across all outbound email sending (campaigns, test emails, replies).
 */
export function getEmailSignature(): string {
  // Base URL for assets — should be the public URL of the deployed app
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";
  const logoUrl = "data:image/png;base64,"; 

  return `
    <div style="margin-top:28px;padding-top:20px;border-top:1px solid #e4e4e7;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
      <table cellpadding="0" cellspacing="0" border="0" style="font-size:13px;line-height:1.5;color:#52525b;">
        <tr>
          <td style="padding-right:16px;vertical-align:top;">
            <!-- Robust Logo Container -->
            <div style="width:64px;height:64px;background-color:#ffffff;border-radius:12px;overflow:hidden;display:block;border:1px solid #f4f4f5;">
              <img src="${logoUrl}" alt="Life180 Labs" width="64" height="64" style="display:block;border:none;outline:none;text-decoration:none;" 
                onerror="this.style.display='none';this.nextElementSibling.style.display='flex';" />
              <div style="display:none;width:100%;height:100%;align-items:center;justify-content:center;background-color:#0ea5e9;color:white;font-weight:bold;font-size:24px;line-height:64px;text-align:center;">
                L
              </div>
            </div>
          </td>
          <td style="vertical-align:top;">
            <p style="margin:0;font-weight:700;font-size:15px;color:#18181b;">GTM Team Life180 Labs</p>
            <div style="margin:8px 0 0 0;font-size:12px;color:#71717a;">
              <p style="margin:0;"><a href="mailto:hello@life180labs.com" style="color:#0ea5e9;text-decoration:none;">hello@life180labs.com</a></p>
              <p style="margin:4px 0 0 0;">📞 +91 98765 43210</p>
              <p style="margin:6px 0 0 0;font-weight:700;color:#1e293b;font-size:10px;text-transform:uppercase;letter-spacing:0.05em;">AI FOR OPERATORS</p>
            </div>
          </td>
        </tr>
      </table>
    </div>`;
}

/**
 * Wraps plain-text email body in properly formatted HTML with the brand signature.
 */
export function formatEmailHTML(body: string): string {
  const bodyParagraphs = body
    .split(/\n\n+/)
    .filter(p => p.trim())
    .map(p => `<p style="margin:0 0 14px 0;line-height:1.6">${p.replace(/\n/g, "<br>")}</p>`)
    .join("");

  return `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;font-size:14px;color:#18181b;max-width:600px">
    ${bodyParagraphs}
    ${getEmailSignature()}
  </div>`;
}
